using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tool: Note-taking ---
var notes = new List<string>();

[Description("Save a research note for later use in the summary.")]
string TakeNote([Description("The note content to save")] string note)
{
    notes.Add(note);
    return $"Note saved ({notes.Count} total).";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0) return "No notes saved yet.";
    return string.Join("\n", notes.Select((n, i) => $"{i + 1}. {n}"));
}

// --- Tool: Web search (simulated) ---
[Description("Search the web for information on a query. Returns search result snippets.")]
string WebSearch([Description("The search query")] string query)
{
    // In production, replace with a real search API (Bing, Google, etc.)
    Console.WriteLine($"  [WebSearch] Searching for: {query}");
    return $"""
        Search results for "{query}":
        1. Wikipedia summary: {query} is a widely discussed topic with many facets including history, current developments, and future outlook.
        2. News article: Recent advances in {query} have led to significant breakthroughs in 2026, with experts predicting continued growth.
        3. Research paper abstract: A comprehensive study of {query} reveals key patterns and emerging trends that shape the field.
        4. Industry report: The {query} market is projected to grow substantially, driven by innovation and increased adoption.
        """;
}

// --- Build the AI chat client with tools ---
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch),
        AIFunctionFactory.Create(TakeNote),
        AIFunctionFactory.Create(GetNotes),
    ]
};

// --- Agent loop ---
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research the given topic thoroughly by:
        1. Searching the web multiple times with different queries to gather diverse information.
        2. Taking notes on the key findings from each search.
        3. After gathering enough information, retrieve your notes and produce a well-structured summary.

        Always search at least 3 times with different angles before summarizing.
        Use the TakeNote tool to record important facts as you find them.
        End with a comprehensive summary of your findings.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

if (notes.Count > 0)
{
    Console.WriteLine("\n=== Raw Notes ===");
    foreach (var (note, idx) in notes.Select((n, i) => (n, i)))
    {
        Console.WriteLine($"  {idx + 1}. {note}");
    }
}

