         Search results for "{query}":
         1. Wikipedia summary: {query} is a widely discussed topic with many facets including history, current developments, and future outlook.
         2. News article: Recent advances in {query} have led to significant breakthroughs in 2026, with experts predicting continued growth.
         3. Research paper abstract: A comprehensive study of {query} reveals key patterns and emerging trends that shape the field.
         4. Industry report: The {query} market is projected to grow substantially, driven by innovation and increased adoption.
         """;
 }

 // --- Build the AI chat client with tools ---
 IChatClient client = new OpenAIClient(openAiKey)
     .GetChatClient(model)
     .AsIChatClient()
     .AsBuilder()
     .UseFunctionInvocation()
     .Build();

 var chatOptions = new ChatOptions
 {
     Tools =
     [
         AIFunctionFactory.Create(WebSearch),
         AIFunctionFactory.Create(TakeNote),
         AIFunctionFactory.Create(GetNotes),
     ]
 };

 // --- Agent loop ---
 Console.WriteLine("=== Research Agent ===");
 Console.Write("Enter a topic to research: ");
 var topic = Console.ReadLine()?.Trim();
 if (string.IsNullOrEmpty(topic))
 {
     Console.WriteLine("No topic provided. Exiting.");
     return;
 }

 Console.WriteLine($"\nResearching: {topic}\n");

